import csv
import json
import re
from pathlib import Path


ROOT = Path("/root")


def load_json(path: Path):
    with path.open() as f:
        return json.load(f)


def load_csv(path: Path):
    with path.open(newline="") as f:
        return list(csv.DictReader(f))


_ISO_WEEK_RE = re.compile(r"^\d{4}-W\d{2}$")


def is_iso_week(s: str) -> bool:
    return bool(_ISO_WEEK_RE.match(s or ""))


def as_float(x, *, field_name: str):
    if x is None:
        raise ValueError(f"Missing required numeric field: {field_name}")
    s = str(x).strip()
    if s == "":
        raise ValueError(f"Blank required numeric field: {field_name}")
    return float(s)


def as_int(x, *, field_name: str):
    if x is None:
        raise ValueError(f"Missing required int field: {field_name}")
    s = str(x).strip()
    if s == "":
        raise ValueError(f"Blank required int field: {field_name}")
    return int(s)


def round2(x: float) -> float:
    # Ensure we keep JSON numbers as floats (not Decimal/str) and stable rounding.
    return float(f"{x:.2f}")


def flatten_panels(panel_manifest: dict):
    clusters = panel_manifest.get("service_clusters", [])
    panels = []
    for c in clusters:
        for p in c.get("panels", []):
            panels.append(p)
    return panels


def main():
    panel_manifest = load_json(ROOT / "panel_manifest.json")
    shipper_cost_rows = load_csv(ROOT / "shipper_cost.csv")
    contract_term_rows = load_csv(ROOT / "contract_terms.csv")
    network_adj_rows = load_csv(ROOT / "network_adjustments.csv")
    capacity_override_rows = load_csv(ROOT / "lab_capacity_overrides.csv")
    holdouts = load_json(ROOT / "holdouts.json")
    template = load_json(ROOT / "report_template.json")

    # Step 2: Filter panels by analysis_mode == "review".
    panels = [p for p in flatten_panels(panel_manifest) if p.get("analysis_mode") == "review"]

    # Step 3: Apply holdouts exclude.
    excluded = {
        h.get("panel_code")
        for h in (holdouts.get("holdouts") or [])
        if h.get("holdout_state") == "exclude"
    }
    panels = [p for p in panels if p.get("panel_code") not in excluded]

    # Step 5: Network adjustments lookup.
    network_adj_by_tier = {}
    for r in network_adj_rows:
        tier = (r.get("network_tier") or "").strip()
        if not tier:
            continue
        network_adj_by_tier[tier] = as_float(r.get("network_adjustment_per_run_per_lab_usd"), field_name="network_adjustment_per_run_per_lab_usd")

    # Step 7: Shipper cost lookup.
    shipper_cost_by_class = {}
    for r in shipper_cost_rows:
        cls = (r.get("shipper_class") or "").strip()
        if not cls:
            continue
        shipper_cost_by_class[cls] = as_float(r.get("shipper_cost_usd"), field_name="shipper_cost_usd")

    # Step 6: Lab capacity overrides.
    # Keep approved rows with non-blank rev and active_labs; pick highest numeric rev per panel_code.
    overrides_by_panel_code = {}
    for r in capacity_override_rows:
        if (r.get("approval") or "").strip() != "approved":
            continue
        panel_code = (r.get("panel_code") or "").strip()
        rev_s = (r.get("rev") or "").strip()
        labs_s = (r.get("active_labs") or "").strip()
        if not panel_code or not rev_s or not labs_s:
            continue
        try:
            rev = int(rev_s)
        except ValueError:
            continue
        labs = int(labs_s)
        current = overrides_by_panel_code.get(panel_code)
        if current is None or rev > current[0]:
            overrides_by_panel_code[panel_code] = (rev, labs)

    # Step 4: Contract term resolution: match panel_ref against panel_name or any alias_labels.
    # Keep status_flag == current, and among those pick latest effective_week.
    def resolve_base_payment(panel: dict) -> float:
        panel_name = panel.get("panel_name") or ""
        aliases = panel.get("alias_labels") or []
        refs = {panel_name, *aliases}

        matches = []
        for r in contract_term_rows:
            if (r.get("status_flag") or "").strip() != "current":
                continue
            panel_ref = (r.get("panel_ref") or "").strip()
            if panel_ref in refs:
                matches.append(r)

        if not matches:
            raise ValueError(f"No current contract_terms match for panel_code={panel.get('panel_code')} refs={sorted(refs)}")

        def sort_key(r):
            ew = (r.get("effective_week") or "").strip()
            # If ISO-like, string comparison preserves chronological order; otherwise, still compare strings.
            return (0 if is_iso_week(ew) else 1, ew)

        best = max(matches, key=sort_key)
        return as_float(best.get("base_payment_per_run_per_lab_usd"), field_name="base_payment_per_run_per_lab_usd")

    panel_outputs = []

    for p in panels:
        panel_code = p.get("panel_code")
        if not panel_code:
            raise ValueError("panel_code missing in panel manifest")

        base_payment = resolve_base_payment(p)
        network_tier = (p.get("network_tier") or "").strip()
        network_adj = float(network_adj_by_tier.get(network_tier, 0.0))

        shipper_class = (p.get("shipper_class") or "").strip()
        if shipper_class not in shipper_cost_by_class:
            raise ValueError(f"No shipper cost found for panel_code={panel_code} shipper_class={shipper_class}")
        shipper_cost_usd = float(shipper_cost_by_class[shipper_class])

        default_active_labs = as_int(p.get("default_active_labs"), field_name="default_active_labs")
        active_labs = overrides_by_panel_code.get(panel_code, (None, default_active_labs))[1]
        active_labs = int(active_labs)

        reagent_cost_per_1000 = as_float(p.get("reagent_cost_per_1000_tests_usd"), field_name="reagent_cost_per_1000_tests_usd")
        tests_14 = as_float(p.get("tests_per_lab_per_run_14_day"), field_name="tests_per_lab_per_run_14_day")
        tests_28 = as_float(p.get("tests_per_lab_per_run_28_day"), field_name="tests_per_lab_per_run_28_day")

        total_payment = base_payment + network_adj

        def compute_model(*, runs_per_year: float, tests_per_lab_per_run: float):
            annual_revenue = total_payment * active_labs * runs_per_year
            annual_reagent_cost = reagent_cost_per_1000 * active_labs * tests_per_lab_per_run * runs_per_year / 1000.0
            # shipper_cost_usd is per shipment/run; one shipment per run.
            annual_shipper_cost = shipper_cost_usd * runs_per_year
            annual_margin = annual_revenue - annual_reagent_cost - annual_shipper_cost
            return {
                "runs_per_year": runs_per_year,
                "annual_revenue": annual_revenue,
                "annual_reagent_cost": annual_reagent_cost,
                "annual_shipper_cost": annual_shipper_cost,
                "annual_margin": annual_margin,
            }

        m14 = compute_model(runs_per_year=26.0, tests_per_lab_per_run=tests_14)
        m28 = compute_model(runs_per_year=13.0, tests_per_lab_per_run=tests_28)

        panel_outputs.append(
            {
                "panel_code": panel_code,
                "panel_name": p.get("panel_name"),
                "network_tier": network_tier,
                "shipper_class": shipper_class,
                "active_labs": active_labs,
                "base_payment_per_run_per_lab_usd": round2(base_payment),
                "network_adjustment_per_run_per_lab_usd": round2(network_adj),
                "total_payment_per_run_per_lab_usd": round2(total_payment),
                "annual_revenue_14_day_usd": round2(m14["annual_revenue"]),
                "annual_reagent_cost_14_day_usd": round2(m14["annual_reagent_cost"]),
                "annual_shipper_cost_14_day_usd": round2(m14["annual_shipper_cost"]),
                "annual_margin_14_day_usd": round2(m14["annual_margin"]),
                "annual_revenue_28_day_usd": round2(m28["annual_revenue"]),
                "annual_reagent_cost_28_day_usd": round2(m28["annual_reagent_cost"]),
                "annual_shipper_cost_28_day_usd": round2(m28["annual_shipper_cost"]),
                "annual_margin_28_day_usd": round2(m28["annual_margin"]),
                "annual_margin_difference_28_minus_14_usd": round2(m28["annual_margin"] - m14["annual_margin"]),
            }
        )

    # Step 10: Sort by panel_code ascending.
    panel_outputs.sort(key=lambda x: x["panel_code"])

    # Step 11: Totals from panel outputs (rounded values) for internal consistency.
    total_14 = sum(p["annual_margin_14_day_usd"] for p in panel_outputs)
    total_28 = sum(p["annual_margin_28_day_usd"] for p in panel_outputs)
    total_diff = total_28 - total_14
    abs_diff = abs(total_diff)

    totals = {
        "total_annual_margin_14_day_usd": round2(total_14),
        "total_annual_margin_28_day_usd": round2(total_28),
        "total_annual_margin_difference_28_minus_14_usd": round2(total_diff),
        "absolute_total_margin_difference_usd": round2(abs_diff),
    }

    # Step 12: Decision.
    decision = "adopt_28_day" if totals["absolute_total_margin_difference_usd"] < 6000.0 else "keep_14_day"
    justification = (
        f"Decision rule: adopt_28_day if absolute_total_margin_difference_usd < 6000.00; "
        f"computed absolute difference is {totals['absolute_total_margin_difference_usd']:.2f}."
    )

    # Step 13: Build output JSON, preserving metadata and audit_notes exactly.
    out = {
        "metadata": template.get("metadata"),
        "audit_notes": template.get("audit_notes"),
        "analysis": {
            "assumptions": {
                "runs_per_year_14_day": 26,
                "runs_per_year_28_day": 13,
                "shipper_cost_interpretation": "shipper_cost_usd is per shipment/run; annual_shipper_cost = shipper_cost_usd * runs_per_year",
            },
            "panels": panel_outputs,
            "totals": totals,
            "recommendation": {
                "decision": decision,
                "justification": justification,
                "threshold_absolute_total_margin_difference_usd": 6000.0,
            },
        },
    }

    with (ROOT / "diagpanel_policy_report.json").open("w") as f:
        json.dump(out, f, indent=2)

    # Step 14: Summary markdown (4–8 non-empty lines).
    with (ROOT / "diagpanel_policy_summary.md").open("w") as f:
        f.write(f"Total 14-day margin (USD): ${totals['total_annual_margin_14_day_usd']:.2f}\n")
        f.write(f"Total 28-day margin (USD): ${totals['total_annual_margin_28_day_usd']:.2f}\n")
        f.write(f"Absolute difference (USD): ${totals['absolute_total_margin_difference_usd']:.2f}\n")
        f.write(f"Final decision slug: {decision}\n")
        f.write(f"Justification: {justification}\n")


if __name__ == "__main__":
    main()

